import os
import logging
from taf.transport.ssh import ssh
from taf.hw.mcs.exception import StartMCSProcessFailed


class EmptyStarter(object):

    def start(self):
        pass

    def stop(self):
        pass


class SSHStarter(object):

    def __init__(self, ip, username, password, mcs_app_path, mcs_app_name):
        self._ssh_connection = ssh()
        self._ip = ip
        self._username = username
        self._password = password
        self._mcs_app_path = mcs_app_path
        self._mcs_app_name = mcs_app_name

    def start(self):
        self._connect_to_ctrl_pc()
        self._enable_mcs_server_is_running()

    def _enable_mcs_server_is_running(self):
        if self._is_mcs_process_started():
            self._stop_mcs_process()

        self._start_mcs_process()
        if not self._is_mcs_process_started():
            raise StartMCSProcessFailed("Start MCS Server fail!")

    def _start_mcs_process(self):
        start_command = os.path.join(self._mcs_app_path, self._mcs_app_name)
        command = "nohup {start_command} 2>&1 &".format(start_command=start_command)
        logging.debug("start MCS process with command={}".format(command))
        self._ssh_connection.execute(command, connection='ctrl_pc')

    def _is_mcs_process_started(self):
        output = self._ssh_connection.execute("tasklist", connection='ctrl_pc')
        if self._mcs_app_name in output:
            logging.debug("MCS Server is starting, no need start again.")
            return True
        return False

    def _connect_to_ctrl_pc(self):
        self._ssh_connection.connect_to(self._ip, username=self._username, password=self._password, alias='ctrl_pc')
        logging.debug("Connect to MCS ctrl pc {} successfully".format(self._ip))

    def stop(self):
        self._stop_mcs_process()
        self._disconnect_to_ctrl_pc()

    def _stop_mcs_process(self):
        output = self._ssh_connection.execute("tasklist", connection='ctrl_pc')
        pids = self._get_mcs_process_pid(output)
        base_kill_command = 'taskkill /F'
        for pid in pids:
            kill_command = '{} /PID {}'.format(base_kill_command, pid)
            logging.info("execute " + kill_command)
            self._ssh_connection.execute(kill_command, connection='ctrl_pc')

    def _get_mcs_process_pid(self, process_info):
        pid = []
        for line in process_info.split('\r\n'):
            if self._mcs_app_name in line or "bash.exe" in line:
                pid.append(line.split()[1])
        return pid

    def _disconnect_to_ctrl_pc(self):
        self._ssh_connection.disconnect(connection='ctrl_pc')
